+          assert.equal(undone.error, null, label);
+        }
+      } else if (operation === "update") {
+        const newSpaceId = localRefs[newSpace!];
+        if (typeof newSpaceId !== "number") assert.fail(`unknown ${newSpace}`);
+        await client
+          .from("LocalAccess")
+          .update({ space_id: newSpaceId })
